/* Timeline data. k = evidence tier: rec (documented), wit (witnessed), clm (claimed), myt (tradition), hoax (discredited)
   e = era key. w = Wikipedia search, v = video search, l = direct primary links. */
window.ERAS = [
  { id: "a", name: "Ancient and sacred", span: "Up to 1500 CE", note: "Texts and traditions about beings who came down from the sky and taught." },
  { id: "b", name: "Portents and airships", span: "1500 to 1939", note: "Broadsheets, legends, miracle crowds and the first mass sighting waves." },
  { id: "c", name: "The saucer age", span: "1940 to 1969", note: "War, the bomb, Roswell, and 22 years of official Air Force study." },
  { id: "d", name: "High strangeness", span: "1970 to 1999", note: "Abductions, nuclear bases, triangles, and the first reverse-engineering claims." },
  { id: "e", name: "The quiet build", span: "2000 to 2016", note: "Navy radar, a secret Pentagon program, and cases that surfaced years later." },
  { id: "f", name: "The disclosure era", span: "2017 to today", note: "Leaked video, sworn testimony, legislation and the government file releases." }
];

window.TIERS = {
  rec:  { name: "Documented", desc: "Official records, sensor data or sworn testimony establish that the event happened. What it was may still be disputed." },
  wit:  { name: "Witnessed",  desc: "Several credible witnesses, sometimes with physical traces, but no hard public record." },
  clm:  { name: "Claimed",    desc: "Rests mainly on one source, late testimony or evidence nobody outside has examined." },
  myt:  { name: "Tradition",  desc: "A sacred text, oral tradition or monument. The sky-visitor reading is a modern interpretation." },
  hoax: { name: "Discredited", desc: "Shown to be a hoax, a fabrication or a deliberate deception." }
};

window.TIMELINE = [
/* ───────────── A · Ancient and sacred ───────────── */
{ y:-2100, d:"c. 2500 to 500 BCE", e:"a", k:"myt", g:["myth"], t:"The Anunnaki and the seven sages", p:"Sumer and Babylon, Mesopotamia",
  s:`Sumerian and Akkadian texts describe the Anunnaki, gods of sky and earth who decide human fate, and the apkallu, seven sages sent by the god Enki before the flood to teach building, crafts and law. The priest Berossus (c. 290 BCE) retold it as Oannes, a fish-bodied being who rose from the Persian Gulf each day to teach writing, mathematics and farming.`,
  c:`Zecharia Sitchin's 1976 claim that the Anunnaki were astronauts from a planet called Nibiru who engineered humans rests on translations Assyriologists reject. The tablets describe gods in religious terms.`,
  w:"Apkallu", v:"Anunnaki apkallu Oannes Sumerian texts explained" },
{ y:-1450, d:"c. 1450 BCE (alleged)", e:"a", k:"hoax", g:["myth","sighting"], t:"The Tulli Papyrus and the circles of fire", p:"Egypt, reign of Thutmose III",
  s:`A supposed Egyptian papyrus describes "circles of fire" crossing the sky and multiplying over several days while the pharaoh's army watched. It has been quoted in UFO books since 1953 as the oldest written sighting.`,
  c:`No original has ever been produced. The text traces to a transcription of an alleged copy once owned by a Vatican Museum official, and the Vatican says it holds no such papyrus. Treat it as unverified at best.`,
  w:"Tulli Papyrus" },
{ y:-593, d:"c. 593 BCE", e:"a", k:"myt", g:["myth"], t:"Ezekiel's wheel within a wheel", p:"Chebar canal, Babylonia",
  s:`Ezekiel describes a storm cloud flashing fire, four winged living creatures, and beside each a wheel within a wheel with rims full of eyes that rose when the creatures rose, all beneath a throne. NASA engineer Josef Blumrich set out to debunk the spacecraft reading and instead wrote The Spaceships of Ezekiel (1974) defending it.`,
  c:`Biblical scholars read the vision as throne-chariot imagery drawn from Babylonian temple art. Blumrich's lander design required reshaping details the text does not contain.`,
  w:"Ezekiel's vision of the chariot", v:"Ezekiel wheel within a wheel Blumrich spaceships" },
{ y:-400, d:"c. 500 BCE to 400 CE", e:"a", k:"myt", g:["myth"], t:"Vimanas, the flying palaces", p:"India",
  s:`The Ramayana's Pushpaka vimana is a self-moving aerial chariot that carries Rama home from Lanka. The Mahabharata describes sky cities and divine weapons that burn armies. Ancient-astronaut writers treat these passages as memories of aircraft and energy weapons.`,
  c:`The epics are sacred poetry composed over centuries. The supposed technical manual, the Vaimanika Shastra, surfaced in the 20th century as a psychic dictation, and a 1974 Indian Institute of Science study found its craft could not fly.`,
  w:"Vimana", v:"vimana Ramayana Mahabharata flying machines" },
{ y:-250, d:"c. 300 to 100 BCE", e:"a", k:"myt", g:["myth","contact"], t:"The Watchers come down on Mount Hermon", p:"Book of Enoch, Second Temple Judea",
  s:`Two hundred angels led by Shemihazah descend on Mount Hermon, take human wives and teach forbidden arts. Azazel teaches metalworking, weapons and cosmetics. Others teach astrology, the reading of signs and the cutting of roots. Their giant children, the Nephilim, ruin the earth until the flood. Genesis 6 gives the same story in four verses.`,
  c:`This is the cleanest ancient template for beings who descend, teach technology and interbreed. It is also a Jewish apocalypse written to explain the origin of evil, not a report of an event.`,
  w:"Watcher (angel)", v:"Book of Enoch Watchers Mount Hermon" },
{ y:-74, d:"218 to 74 BCE", e:"a", k:"wit", g:["sighting"], t:"Rome logs phantom ships and a silver jar", p:"Italy and Phrygia",
  s:`Livy records "phantom ships gleaming in the sky" in 218 BCE. Plutarch writes that in 74 BCE, as the armies of Lucullus and Mithridates closed, the sky split and a large flame-like body shaped like a wine jar and coloured like molten silver fell between them. Both armies withdrew.`,
  c:`Romans recorded sky prodigies as omens for the state. Plutarch wrote about 170 years after the battle, and the description fits a daylight fireball or meteorite fall.`,
  w:"Battle of the Rhyndacus (73 BC) Plutarch flame silver", v:"Roman UFO sightings Livy Plutarch prodigies" },
{ y:200, d:"c. 100 BCE to 1500 CE", e:"a", k:"myt", g:["myth"], t:"Feathered serpents, Viracocha and the Ant People", p:"Mesoamerica, the Andes, the Hopi mesas",
  s:`Quetzalcoatl and Kukulkan are credited with giving maize, the calendar and the arts. Viracocha rises from Lake Titicaca, makes the sun and the first people, walks the Andes teaching, then leaves across the Pacific. Hopi tradition tells of Ant People who sheltered the ancestors underground while earlier worlds were destroyed, and of kachina spirits who come from the peaks.`,
  c:`The image of a bearded foreign teacher owes much to Spanish chroniclers writing after the conquest. These are living religious traditions, and their keepers do not describe them as accounts of spacecraft.`,
  w:"Viracocha", v:"Viracocha Quetzalcoatl Hopi Ant People legend" },
{ y:300, d:"Recorded 1931 to 1956", e:"a", k:"myt", g:["myth"], t:"The Nommo and the Sirius mystery", p:"Dogon country, Mali",
  s:`French anthropologists Marcel Griaule and Germaine Dieterlen reported that Dogon elders spoke of the Nommo, amphibious ancestral spirits who came down in an ark with fire and thunder, and of an invisible, heavy companion star to Sirius. Robert Temple's The Sirius Mystery (1976) argued the knowledge came from visitors.`,
  c:`Anthropologist Walter van Beek spent years with the Dogon and reported in 1991 that he found no such Sirius lore. The likeliest sources are Griaule's own prompting or earlier European contact.`,
  w:"Nommo", v:"Dogon Sirius mystery Nommo" },
{ y:400, d:"c. 2000 BCE to today", e:"a", k:"myt", g:["myth"], t:"The Wandjina, painted without mouths", p:"Kimberley, Western Australia",
  s:`Rock shelters across the Kimberley hold large white figures with huge dark eyes, haloed heads and no mouths. For the Worrorra, Ngarinyin and Wunambal peoples these are the Wandjina, sky beings who shaped the land, brought law and rain, then lay down in the caves and became their own paintings.`,
  c:`The resemblance to modern Grey imagery is striking, and it is a coincidence of style. Traditional owners say the halos are cloud and lightning, and that a mouth would let out enough rain to drown the world.`,
  w:"Wandjina", v:"Wandjina rock art Kimberley" },

/* ───────────── B · Portents and airships ───────────── */
{ y:1561, d:"14 April 1561", e:"b", k:"wit", g:["sighting"], t:"The battle in the sky over Nuremberg", p:"Nuremberg, Holy Roman Empire",
  s:`A broadsheet by Hans Glaser reports that at dawn many townspeople saw spheres, crosses and long tubes that released more spheres, all moving against one another for about an hour before falling to earth in smoke. A similar sheet from Basel in 1566 describes black spheres racing before the sun.`,
  c:`Broadsheets were the tabloids of their day and framed sky events as divine warnings. The shapes match a complex sun dog and halo display seen at sunrise.`,
  w:"1561 celestial phenomenon over Nuremberg", v:"1561 Nuremberg celestial phenomenon" },
{ y:1803, d:"22 February 1803", e:"b", k:"myt", g:["contact"], t:"Utsuro-bune, the hollow ship", p:"Hitachi Province, Japan",
  s:`Edo-period texts tell of fishermen who towed in a round vessel about five metres wide, with an iron-banded base, crystal windows and unknown writing inside. A young woman in strange clothes stepped out holding a box she let nobody touch. The villagers pushed the craft back out to sea.`,
  c:`The drawings look uncannily like a saucer, but the story appears only in collections of curious tales written about twenty years later. Japanese folklorists class it as a legend with older variants.`,
  w:"Utsuro-bune", v:"Utsuro-bune 1803 Japan hollow ship" },
{ y:1897, d:"November 1896 to April 1897", e:"b", k:"wit", g:["sighting","crash"], t:"The mystery airships", p:"California to the Midwest, USA",
  s:`Starting in Sacramento, thousands of Americans reported cigar-shaped craft with searchlights crossing the night sky, years before any working airship flew in the US. On 17 April 1897 a Dallas newspaper said one hit a windmill in Aurora, Texas, and that its pilot, "not an inhabitant of this world", was buried in the town cemetery.`,
  c:`Newspapers of the period printed hoaxes freely. The Aurora story is generally credited to a local correspondent trying to revive a dying town, and no wreckage or grave has been confirmed.`,
  w:"Mystery airship", v:"1897 mystery airship Aurora Texas" },
{ y:1917, d:"13 October 1917", e:"b", k:"wit", g:["sighting","contact"], t:"The Miracle of the Sun", p:"Fátima, Portugal",
  s:`Tens of thousands gathered after three shepherd children said a lady from heaven had promised a sign. Witnesses, including journalists from secular papers, reported that the sun became a dull spinning disc, threw off colours, and plunged toward the crowd before returning. Jacques Vallée and others class it with UFO events. The Church approved it in 1930.`,
  c:`No observatory recorded anything unusual, and not everyone present saw it. Staring at the sun produces afterimages and apparent motion, and the crowd arrived expecting a miracle.`,
  w:"Miracle of the Sun", v:"Miracle of the Sun Fatima 1917" },
{ y:1933, d:"1933 (alleged)", e:"b", k:"clm", g:["crash","retrieval"], t:"The Magenta saucer", p:"Magenta, Lombardy, Italy",
  s:`David Grusch said in 2023 that Mussolini's government recovered a largely intact craft in northern Italy in 1933, studied it under a secret cabinet, and that the US obtained it near the end of the war. He called it the earliest retrieval he was aware of.`,
  c:`The story rests on anonymous documents mailed to Italian researchers from 1996 onward. Their paper and ink date to the right period, but their authorship and content have never been verified.`,
  w:"David Grusch UFO whistleblower claims", v:"1933 Magenta UFO crash Italy Grusch" },

/* ───────────── C · The saucer age ───────────── */
{ y:1942.15, d:"24 to 25 February 1942", e:"c", k:"rec", g:["sighting","gov"], t:"The Battle of Los Angeles", p:"Los Angeles, California",
  s:`Eleven weeks after Pearl Harbor, radar picked up an unknown target and coastal batteries fired more than 1,400 anti-aircraft shells into the night sky over a blacked-out city. No bombs fell and no aircraft was found. A retouched newspaper photo of searchlights converging on a glowing shape became one of the most reproduced UFO images.`,
  c:`The Navy called it a false alarm within hours. A 1983 Air Force history blamed weather balloons and war nerves, with shell bursts mistaken for targets.`,
  w:"Battle of Los Angeles", v:"Battle of Los Angeles 1942" },
{ y:1944.9, d:"November 1944 to 1945", e:"c", k:"wit", g:["sighting"], t:"Foo fighters", p:"Europe and the Pacific",
  s:`Allied night-fighter crews, first the US 415th Night Fighter Squadron over the Rhine, reported balls of red, orange and white light that paced their aircraft, turned with them and could not be shaken or shot. Each side assumed a secret enemy weapon. After the war it emerged that German and Japanese pilots had seen them too.`,
  c:`Suggested causes include St. Elmo's fire, ball lightning and afterimages from flak. The CIA's 1953 Robertson Panel judged them unexplained but harmless.`,
  w:"Foo fighter", v:"foo fighters WWII pilots lights" },
{ y:1945.6, d:"16 August 1945 (alleged)", e:"c", k:"clm", g:["crash","retrieval","nuclear"], t:"The Trinity crash", p:"San Antonio, New Mexico",
  s:`In Trinity: The Best-Kept Secret (2021), Jacques Vallée and Paola Harris present two men who say that as boys, a month after the first atomic test and a few miles from it, they watched an avocado-shaped craft crash, saw small beings moving inside, and watched the Army haul it away.`,
  c:`The account surfaced decades later from childhood memories. Critics have documented shifting details and no supporting records. Vallée stands by the witnesses.`,
  w:"Jacques Vallée", v:"Jacques Vallee Trinity 1945 San Antonio crash" },
{ y:1946.5, d:"May to December 1946", e:"c", k:"wit", g:["sighting","gov"], t:"Ghost rockets over Scandinavia", p:"Sweden and Finland",
  s:`Swedes filed about 2,000 reports of fast, wingless, rocket-like objects, around 200 of them with radar returns. Several were seen diving into lakes. The Swedish defence staff investigated with the army and navy, searched lake beds and recovered nothing.`,
  c:`Report peaks line up with meteor showers. The military suspected Soviet tests of captured V-2 technology but never found proof either way.`,
  w:"Ghost rockets", v:"ghost rockets Sweden 1946" },
{ y:1947.48, d:"24 June 1947", e:"c", k:"wit", g:["sighting"], t:"Kenneth Arnold and the nine objects", p:"Mount Rainier, Washington",
  s:`Private pilot Kenneth Arnold watched nine bright, crescent-like objects fly in a chain past Mount Rainier. Timing them between two peaks, he estimated well over 1,200 mph, faster than anything flying. He said they moved like a saucer skipped across water. Headline writers coined "flying saucer", and hundreds of reports followed within weeks.`,
  c:`Proposed explanations include mirages, pelicans and meteors. None has been established, and the Air Force file lists the case as a mirage.`,
  w:"Kenneth Arnold UFO sighting", v:"Kenneth Arnold 1947 flying saucer sighting" },
{ y:1947.52, d:"Early July 1947", e:"c", k:"rec", g:["crash","retrieval","gov"], t:"Roswell", p:"Lincoln County, New Mexico",
  s:`Rancher Mac Brazel found a field of strange debris. On 8 July the Roswell Army Air Field announced it had recovered a "flying disc". Within a day the Army said it was a weather balloon. The story died until 1978, when intelligence officer Jesse Marcel said the material was not of this earth. Witnesses then added a second site, bodies and threats.`,
  c:`The Air Force said in 1994 that the debris came from Project Mogul, a secret balloon train built to detect Soviet nuclear tests, and in 1997 that the body stories were confused memories of crash-test dummies dropped in the 1950s.`,
  w:"Roswell incident", v:"Roswell 1947 incident documentary" },
{ y:1947.73, d:"23 September 1947", e:"c", k:"rec", g:["gov"], t:"The Twining memo and Project Sign", p:"Wright Field, Ohio",
  s:`Lt. Gen. Nathan Twining, head of Air Materiel Command, wrote that the phenomenon was "something real and not visionary or fictitious" and listed disc shapes, extreme climb rates and formation flying. The Air Force opened Project Sign in 1948. According to Blue Book chief Edward Ruppelt, Sign's staff drafted an estimate favouring an interplanetary origin, and the Chief of Staff rejected it for lack of proof.`,
  c:`Twining also noted the complete absence of crash debris. Sign's successor, Project Grudge, was set up to explain reports away.`,
  w:"Twining memo UFO Project Sign", v:"Twining memo 1947 Project Sign Estimate of the Situation",
  l:[["Air Force UFO records, National Archives","https://www.archives.gov/research/military/air-force/ufos"]] },
{ y:1948.02, d:"7 January 1948", e:"c", k:"rec", g:["sighting","gov"], t:"Captain Mantell dies chasing an object", p:"Fort Knox, Kentucky",
  s:`After state police and a base tower reported a large bright object, Kentucky Air National Guard pilot Thomas Mantell climbed after it in an F-51 without oxygen. He reported something metallic and tremendous in size, passed out at altitude and crashed. He is the first death linked to a UFO chase.`,
  c:`The Navy was flying secret Skyhook research balloons, huge and reflective at 60,000 feet. One was probably in the area.`,
  w:"Mantell UFO incident", v:"Mantell UFO incident 1948" },
{ y:1949, d:"1948 to 1951", e:"c", k:"rec", g:["sighting","nuclear","gov"], t:"Green fireballs over the atomic labs", p:"Los Alamos and Sandia, New Mexico",
  s:`Scientists and security staff at the nation's nuclear weapons laboratories repeatedly reported bright green fireballs moving on flat, silent paths. Meteor expert Lincoln LaPaz, who saw one, concluded they were not natural. The Air Force ran Project Twinkle to photograph them. It is the first cluster tying the phenomenon to nuclear sites.`,
  c:`Project Twinkle recorded little and closed in 1951 with a finding of natural causes. Other researchers have suggested unusual meteors.`,
  w:"Green fireballs", v:"green fireballs Los Alamos Project Twinkle" },
{ y:1950.36, d:"11 May 1950", e:"c", k:"wit", g:["sighting","photo"], t:"The McMinnville photographs", p:"McMinnville, Oregon",
  s:`Farmers Evelyn and Paul Trent took two photographs of a metallic disc with an off-centre mast over their yard. Life magazine printed them. The Air Force-funded Condon study, hostile to most cases, called this one consistent with a real, distant, physical object.`,
  c:`Later analyses of shadows and geometry argue for a small model hanging from the overhead wires. The Trents never sought money and never changed their story.`,
  w:"McMinnville UFO photographs", v:"McMinnville UFO photographs 1950 Trent" },
{ y:1952.55, d:"19 to 27 July 1952", e:"c", k:"rec", g:["sighting","gov"], t:"UFOs over the Capitol", p:"Washington, D.C.",
  s:`On two consecutive weekends, radar at National Airport and Andrews Air Force Base tracked unknown targets over restricted airspace, while pilots and controllers saw lights where the blips were. Jets scrambled. The Air Force held its largest press conference since the war to calm the country.`,
  c:`Generals blamed temperature inversions bending radar beams. The controllers on duty, who knew what inversions looked like, never accepted it.`,
  w:"1952 Washington, D.C., UFO incident", v:"1952 Washington DC UFO flap" },
{ y:1952.9, d:"20 November 1952", e:"c", k:"hoax", g:["contact"], t:"Adamski meets a Venusian", p:"Desert Center, California",
  s:`George Adamski said he met Orthon, a handsome long-haired visitor from Venus who warned about nuclear weapons. His books sold worldwide and started the contactee movement. Orthon is the first of the tall, blond Space Brothers later called Nordics.`,
  c:`Adamski's saucer photographs match household objects, his space travel claims contradicted what probes later found, and Venus cannot support such life.`,
  w:"George Adamski", v:"George Adamski contactee Orthon" },
{ y:1953.05, d:"January 1953", e:"c", k:"rec", g:["gov"], t:"The Robertson Panel", p:"CIA, Washington, D.C.",
  s:`Worried that floods of saucer reports could clog air defence channels, the CIA convened a panel of scientists. After about twelve hours of review it recommended a public education campaign to strip UFOs of their aura, using mass media, and suggested watching civilian UFO groups. It is the documentary root of the cover-up charge.`,
  c:`The panel found no threat and no evidence of visitors. Its goal was to cut noise during the Cold War, which is different from hiding a secret, though it did shape decades of official ridicule.`,
  w:"Robertson Panel", v:"Robertson Panel 1953 CIA UFO",
  l:[["CIA reading room: UFOs, Fact or Fiction?","https://www.cia.gov/readingroom/collection/ufos-fact-or-fiction"]] },
{ y:1955.64, d:"21 August 1955", e:"c", k:"wit", g:["contact"], t:"The Kelly–Hopkinsville goblins", p:"Christian County, Kentucky",
  s:`Eleven people at a farmhouse said that small silvery creatures with huge eyes, pointed ears and clawed hands approached repeatedly for hours while the men shot at them without effect. The family fled to the police station. Officers found bullet damage and frightened, sober witnesses.`,
  c:`Investigators have proposed territorial great horned owls seen in poor light, on a night when meteors were reported nearby.`,
  w:"Kelly–Hopkinsville encounter", v:"Kelly Hopkinsville encounter 1955" },
{ y:1957.84, d:"2 to 3 November 1957", e:"c", k:"wit", g:["sighting"], t:"Levelland: engines die on the highway", p:"Levelland, Texas",
  s:`In about two and a half hours, at least seven drivers on different roads independently told police that a glowing egg-shaped object, roughly 200 feet long, had landed or hovered ahead of them, and that their engines and headlights failed until it left. The sheriff saw a streak of light himself.`,
  c:`Blue Book spent part of one day on site and concluded ball lightning and wet ignition systems. Hynek later called that investigation inadequate.`,
  w:"Levelland UFO case", v:"Levelland UFO case 1957" },
{ y:1961.72, d:"19 to 20 September 1961", e:"c", k:"wit", g:["contact","abduction"], t:"Betty and Barney Hill", p:"White Mountains, New Hampshire",
  s:`A couple driving home at night watched a lit craft descend, then arrived two hours late with no memory of the gap. Under separate hypnosis in 1964 both described being taken aboard and examined by short grey-skinned beings with large eyes. Betty drew a star map later matched by a teacher to Zeta Reticuli. This is the template for the modern abduction story and for the Grey.`,
  c:`Their psychiatrist thought Barney had absorbed Betty's dreams. The star-map match weakened when better stellar distances arrived. Brazil's Antônio Villas Boas told a similar story in 1957.`,
  w:"Barney and Betty Hill incident", v:"Betty and Barney Hill abduction 1961" },
{ y:1964.31, d:"24 April 1964", e:"c", k:"wit", g:["sighting","contact"], t:"Socorro: a policeman and an egg on legs", p:"Socorro, New Mexico",
  s:`Officer Lonnie Zamora broke off a car chase after a roar and a flame. In a gully he saw a white egg-shaped craft on legs with a red insignia, and two small figures in white. It lifted off with a blast and left burned brush and four landing impressions. Blue Book listed it as unidentified, and Hynek called it one of the major cases.`,
  c:`A hot-air balloon prank by students at the nearby mining college has been proposed. No one has ever confessed in a checkable way.`,
  w:"Lonnie Zamora incident", v:"Lonnie Zamora Socorro UFO 1964" },
{ y:1965.94, d:"9 December 1965", e:"c", k:"wit", g:["crash","retrieval"], t:"Kecksburg", p:"Westmoreland County, Pennsylvania",
  s:`A fireball crossed six states and Ontario. Residents of Kecksburg said something came down in the woods: a bronze acorn the size of a small car with markings like hieroglyphs around its rim. They say the Army sealed the area and drove a tarp-covered object out on a flatbed.`,
  c:`Astronomers tracked a meteor that ended over Lake Erie. NASA said in 2005 it had examined fragments of a Soviet satellite, then could not find the records when sued.`,
  w:"Kecksburg UFO incident", v:"Kecksburg UFO incident 1965" },
{ y:1966.22, d:"March 1966", e:"c", k:"rec", g:["sighting","gov"], t:"Swamp gas", p:"Dexter and Hillsdale, Michigan",
  s:`More than a hundred people, including police officers and college students, reported glowing objects over two nights. Blue Book's scientist J. Allen Hynek suggested marsh gas for some of them. The public and press were furious, Michigan congressman Gerald Ford demanded hearings, and the Air Force agreed to fund an independent university study.`,
  c:`Hynek said he was misquoted and badly briefed. The episode began his slow turn from debunker to the field's leading scientific advocate.`,
  w:"Michigan swamp gas UFO 1966 Hynek", v:"1966 Michigan swamp gas UFO Hynek" },
{ y:1966.27, d:"6 April 1966", e:"c", k:"wit", g:["sighting"], t:"Westall", p:"Melbourne, Australia",
  s:`Around 200 students and staff at two schools watched a grey saucer-shaped object descend into a paddock behind pine trees, rise again and leave at speed, chased by light aircraft. Witnesses say men in uniform arrived, the headmaster ordered silence, and a circle of flattened grass was burned.`,
  c:`A runaway high-altitude research balloon from a joint US and Australian radiation test programme has been suggested. Official files on the day have not turned up.`,
  w:"Westall UFO", v:"Westall UFO 1966" },
{ y:1967.2, d:"March 1967", e:"c", k:"rec", g:["nuclear","gov","sighting"], t:"Missiles go dark at Malmstrom", p:"Malmstrom Air Force Base, Montana",
  s:`On 16 March, all ten Minuteman nuclear missiles of Echo Flight dropped offline within seconds. Launch officer Robert Salas says the same happened at his Oscar Flight days later, while guards above reported a glowing red object over the gate. Declassified unit histories confirm the Echo shutdown and mention UFO rumours.`,
  c:`The Air Force traced the failure to an electrical noise pulse in a logic coupler. Unit records say the UFO reports were disproven, and no document confirms the Oscar Flight event.`,
  w:"Malmstrom UFO incident", v:"Malmstrom AFB 1967 UFO Robert Salas missiles" },
{ y:1967.76, d:"4 October 1967", e:"c", k:"rec", g:["crash","gov"], t:"Shag Harbour", p:"Nova Scotia, Canada",
  s:`At least eleven people watched a row of lights descend and hit the water with a bang. Police officers on shore saw a pale light bobbing offshore and trailing yellow foam. The coast guard, fishermen and navy divers searched for days. Canadian government files label the object a UFO.`,
  c:`Nothing was recovered. It remains one of very few cases where government agencies themselves recorded a crash of something they could not identify.`,
  w:"Shag Harbour UFO incident", v:"Shag Harbour UFO 1967" },
{ y:1968.5, d:"1968 to 1969", e:"c", k:"rec", g:["media","gov"], t:"Two books and a closed door", p:"Colorado, Paris, Zürich",
  s:`Erich von Däniken's Chariots of the Gods? sold millions and fixed the ancient-astronaut idea in popular culture. Jacques Vallée's Passport to Magonia argued the opposite of the nuts-and-bolts view: that UFO encounters continue fairy, angel and demon lore. The Air Force's Condon Report found nothing worth further study, and Project Blue Book closed on 17 December 1969 with 12,618 reports, 701 of them unidentified.`,
  c:`Archaeologists fault von Däniken for errors and for denying ancient peoples their own achievements. Critics of Condon note that about a third of the cases in his own report stayed unexplained.`,
  w:"Condon Committee", v:"Project Blue Book closes 1969 Condon report",
  l:[["Project Blue Book records, National Archives","https://www.archives.gov/research/military/air-force/ufos"]] },

/* ───────────── D · High strangeness ───────────── */
{ y:1973.78, d:"11 October 1973", e:"d", k:"wit", g:["contact","abduction"], t:"Pascagoula", p:"Pascagoula, Mississippi",
  s:`Shipyard workers Charles Hickson and Calvin Parker said that while fishing they were floated aboard an oval craft by three grey, wrinkled beings with claw hands and examined by a scanning eye. Left alone in a sheriff's office with a hidden tape running, they did not break character. Parker prayed.`,
  c:`Hickson's polygraph was run by an inexperienced examiner. Additional people who say they saw the craft that night came forward decades later.`,
  w:"Pascagoula Abduction", v:"Pascagoula abduction 1973 Hickson Parker" },
{ y:1975.85, d:"5 November 1975", e:"d", k:"wit", g:["contact","abduction"], t:"Travis Walton vanishes", p:"Apache-Sitgreaves Forest, Arizona",
  s:`Six loggers told police they saw a glowing disc knock their crewmate down with a beam, and fled. Walton was missing for five days during a large search, then reappeared with memories of a table, short large-eyed beings and human-looking figures. The crew were suspected of murder until he returned.`,
  c:`Polygraph results are mixed and disputed. Skeptics point to a logging contract the crew was about to default on. In 2021 one crew member's account changed, which Walton rejects.`,
  w:"Travis Walton incident", v:"Travis Walton 1975 abduction" },
{ y:1976.72, d:"19 September 1976", e:"d", k:"rec", g:["sighting","gov"], t:"The Tehran dogfight", p:"Tehran, Iran",
  s:`Two Iranian F-4 Phantoms were sent after a brilliant object. The first lost instruments and radio on approach and regained them when it turned away. The second got a radar lock, then lost its weapons panel as it tried to fire while a smaller object flew at it. A US Defense Intelligence Agency report circulated to the White House rated the case highly.`,
  c:`Skeptics suggest Jupiter, a meteor shower and a jet with a history of electrical faults. The pilot, later a general, never accepted that.`,
  w:"1976 Tehran UFO incident", v:"1976 Tehran UFO incident F-4" },
{ y:1977.8, d:"1977 to 1978", e:"d", k:"rec", g:["sighting","gov","injury"], t:"Colares and Operation Saucer", p:"Pará, Brazil",
  s:`Villagers on a river island said lights were shooting beams that left burns and puncture marks, and people stopped going out at night. The local doctor treated dozens. The Brazilian Air Force sent a team that spent four months taking hundreds of photographs and wrote reports later released by the government.`,
  c:`The official conclusion was that nothing unusual was found. The team's commander said otherwise in a 1997 interview, shortly before his death.`,
  w:"Colares UFO flap Operação Prato", v:"Colares 1977 Operação Prato UFO Brazil" },
{ y:1978.8, d:"21 October 1978", e:"d", k:"rec", g:["sighting"], t:"Frederick Valentich disappears", p:"Bass Strait, Australia",
  s:`A 20-year-old pilot radioed Melbourne that a large aircraft with four bright lights was orbiting above him, that it was "not an aircraft", and that his engine was rough. Seventeen seconds of metallic scraping followed. Neither he nor the Cessna was found.`,
  c:`He was inexperienced, flying over water at dusk. Disorientation, a graveyard spiral, and misread planets are the leading explanations.`,
  w:"Disappearance of Frederick Valentich", v:"Valentich disappearance 1978 radio transcript" },
{ y:1980.99, d:"26 to 28 December 1980", e:"d", k:"rec", g:["sighting","nuclear","gov"], t:"Rendlesham Forest", p:"RAF Woodbridge and Bentwaters, England",
  s:`US Air Force security police went into the woods after lights and reported a small triangular craft with glyphs on its side. Two nights later deputy base commander Lt. Col. Charles Halt led a team back, recorded raised radiation readings and a live audio tape, and watched lights send beams down near the weapons storage area. His signed memo went to the UK Ministry of Defence.`,
  c:`The Orfordness lighthouse beam lines up with the direction of the lights, a bright fireball was seen that night, and the radiation readings were close to background.`,
  w:"Rendlesham Forest incident", v:"Rendlesham Forest incident Halt tape" },
{ y:1981, d:"29 December 1980", e:"d", k:"wit", g:["sighting","injury"], t:"Cash–Landrum", p:"Huffman, Texas",
  s:`Two women and a child stopped their car for a diamond-shaped object spouting flame over the road, escorted, they said, by about 23 helicopters. The car body grew too hot to touch. All three suffered burns, hair loss and lasting illness. They sued the US government.`,
  c:`The case was dismissed because no agency admitted owning such a craft or flying that many helicopters. Medical records from before the event are thin.`,
  w:"Cash–Landrum incident", v:"Cash Landrum incident 1980" },
{ y:1984, d:"1979 to 1988", e:"d", k:"hoax", g:["gov","media"], t:"Majestic 12 and the Bennewitz affair", p:"Albuquerque, New Mexico",
  s:`Businessman Paul Bennewitz filmed lights over Kirtland Air Force Base and picked up signals he thought were alien. Air Force counterintelligence agent Richard Doty fed him forged stories of treaties and underground bases until he was hospitalised. In 1984 the "MJ-12" papers appeared, describing a secret group running crash recoveries. The FBI marked them completely bogus.`,
  c:`This is the documented case that the US government has planted UFO disinformation. Believers and skeptics both cite it, for opposite reasons.`,
  w:"Majestic 12", v:"Paul Bennewitz Richard Doty Mirage Men",
  l:[["FBI Vault: Majestic 12","https://vault.fbi.gov/Majestic%2012"]] },
{ y:1984.5, d:"1983 to 1986", e:"d", k:"wit", g:["sighting"], t:"The Hudson Valley boomerang", p:"New York and Connecticut",
  s:`Several thousand people, including police officers and engineers, reported a silent V-shaped or boomerang craft as wide as a football field, drifting slowly at low altitude with rows of coloured lights. One sighting had it hovering over the Indian Point nuclear plant.`,
  c:`Pilots from a nearby airfield admitted flying tight night formations with their lights rigged to fool people. Witnesses say what they saw was silent, solid and stationary.`,
  w:"Hudson Valley UFO sightings", v:"Hudson Valley UFO sightings 1980s" },
{ y:1986.88, d:"17 November 1986", e:"d", k:"rec", g:["sighting","gov"], t:"Japan Air Lines flight 1628", p:"Over eastern Alaska",
  s:`The crew of a 747 cargo flight reported two craft with glowing nozzle arrays pacing them, then a walnut-shaped object they judged twice the size of an aircraft carrier. It stayed with them through a full turn for about 50 minutes. FAA and military radar showed intermittent returns. FAA division chief John Callahan kept the data and later said he was told the meeting never happened.`,
  c:`The FAA concluded the radar returns were split images of the 747 itself. Skeptics add Jupiter and Mars, which were bright and in the right part of the sky.`,
  w:"Japan Air Lines Cargo Flight 1628 incident", v:"JAL 1628 UFO 1986 Alaska Callahan" },
{ y:1987, d:"1987 to 1994", e:"d", k:"clm", g:["media","abduction"], t:"The abduction era", p:"United States",
  s:`Whitley Strieber's Communion put the almond-eyed Grey on bestseller lists, and Budd Hopkins's Intruders described repeated abductions and hybrid children. In 1994 Harvard psychiatrist John Mack published case studies of experiencers he found sane and sincere. Harvard reviewed his tenure and let him stay.`,
  c:`Most accounts were recovered under hypnosis, which reliably produces confident false memories. Sleep paralysis accounts for the bedroom visitors.`,
  w:"Alien abduction", v:"John Mack abduction research Harvard" },
{ y:1989.4, d:"May to November 1989", e:"d", k:"clm", g:["retrieval","media"], t:"Bob Lazar and S-4", p:"Las Vegas, Nevada",
  s:`On KLAS-TV with George Knapp, Bob Lazar said he had worked at a site called S-4 near Area 51, studying one of nine recovered discs. He described a reactor fuelled by element 115 producing gravity waves, and a craft he called the sport model. He put Area 51 and reverse engineering into public vocabulary.`,
  c:`The universities he names have no record of him. He did appear in a Los Alamos phone directory. Element 115 was first made in 2003, and every known isotope decays in under a second.`,
  w:"Bob Lazar", v:"Bob Lazar 1989 George Knapp interview S-4" },
{ y:1989.9, d:"November 1989 to April 1990", e:"d", k:"rec", g:["sighting","gov"], t:"The Belgian wave", p:"Belgium",
  s:`Police patrols and thousands of civilians reported large, silent black triangles with a light at each corner. The Belgian Air Force worked with civilian researchers, and on 30 March 1990 two F-16s chasing radar targets recorded lock-ons with sudden changes of height and speed. A general presented the data publicly.`,
  c:`The best-known photograph of the wave was a painted foam model, as its maker admitted in 2011. The radar lock-ons may have been the jets tracking each other or ground clutter.`,
  w:"Belgian UFO wave", v:"Belgian UFO wave 1989 1990 triangle F-16" },
{ y:1990.59, d:"4 August 1990", e:"d", k:"wit", g:["sighting","photo","gov"], t:"The Calvine photograph", p:"Perthshire, Scotland",
  s:`Two hikers photographed a large diamond-shaped object hanging over the hills with a military jet nearby. The negatives went to the Ministry of Defence and vanished. In 2022 researcher David Clarke traced a retired RAF press officer who had kept an original print for 32 years.`,
  c:`Explanations offered include a secret US aircraft, a reflection of a rock in still water, and a hoax. The photographers have never been publicly identified.`,
  w:"Calvine photograph", v:"Calvine UFO photo found David Clarke" },
{ y:1994.71, d:"16 September 1994", e:"d", k:"wit", g:["contact","sighting"], t:"The Ariel School", p:"Ruwa, Zimbabwe",
  s:`At morning break, about 60 children aged six to twelve said silver craft landed in scrub beside the playground, and that small figures in black with large eyes came toward them. Several said they were shown, without words, that the planet was being damaged. John Mack interviewed them on camera. As adults, many still describe the same thing.`,
  c:`Mass suggestion among children is the standard explanation. A bright re-entry had crossed southern Africa two nights earlier and had the region talking about UFOs.`,
  w:"Ariel School UFO incident", v:"Ariel School 1994 Zimbabwe John Mack children" },
{ y:1995.65, d:"28 August 1995", e:"d", k:"hoax", g:["media","retrieval"], t:"The alien autopsy film", p:"London, England",
  s:`Producer Ray Santilli released grainy black-and-white footage of doctors dissecting a six-fingered body, sold as military film from Roswell. It aired in more than 30 countries.`,
  c:`Santilli admitted in 2006 that it was staged in a London flat using a dummy filled with sheep brains and chicken entrails. He calls it a reconstruction of film he says he once saw.`,
  w:"Alien autopsy", v:"alien autopsy 1995 Santilli hoax explained" },
{ y:1996.05, d:"20 January 1996", e:"d", k:"wit", g:["crash","retrieval","contact"], t:"Varginha", p:"Minas Gerais, Brazil",
  s:`Three young women said they saw a crouching creature with oily brown skin, red eyes and three ridges on its head. Witnesses describe a crash days earlier, army trucks and captured beings taken to hospitals. On the 30th anniversary, filmmaker James Fox brought witnesses to Washington, where a neurosurgeon said he had examined a living non-human patient.`,
  c:`The Brazilian military inquiry concluded the women saw a local man with a disability crouching in the rain. No medical record, photograph or tissue has been produced.`,
  w:"Varginha UFO incident", v:"Varginha 1996 Moment of Contact James Fox",
  l:[["The Debrief on the 2026 press conference","https://thedebrief.org/landmark-brazilian-ufo-case-reaches-capitol-hill-as-varginha-incident-turns-30/"]] },
{ y:1997.2, d:"13 March 1997", e:"d", k:"wit", g:["sighting"], t:"The Phoenix Lights", p:"Nevada to Tucson, Arizona",
  s:`For over an hour, thousands of people along a 300-mile track watched a huge V of lights pass silently overhead. Many said it was a single dark craft that blocked the stars. Later that night a row of lights hung over the Estrella mountains and was widely filmed. Governor Fife Symington mocked the event, then said in 2007 that he had seen the craft himself.`,
  c:`The late lights were flares dropped by Air National Guard A-10s over a bombing range. The earlier V is consistent with aircraft in formation, as one amateur astronomer with a telescope reported.`,
  w:"Phoenix Lights", v:"Phoenix Lights 1997 footage" },
{ y:1999.55, d:"July 1999", e:"d", k:"rec", g:["gov"], t:"France's COMETA report", p:"Paris, France",
  s:`A private committee of retired generals, an admiral and former heads of the French space agency and its defence institute reviewed the best cases and sent a 90-page report to the president and prime minister. It concluded that the extraterrestrial hypothesis was the most probable explanation for a hard core of cases, and criticised US secrecy.`,
  c:`COMETA was not an official government body, and French scientists attacked its case selection. France's space agency does still run a public UFO study unit, GEIPAN.`,
  w:"COMETA", v:"COMETA report 1999 France UFO",
  l:[["GEIPAN, the French space agency's UAP unit","https://www.geipan.fr/"]] },

/* ───────────── E · The quiet build ───────────── */
{ y:2001.35, d:"9 May 2001", e:"e", k:"clm", g:["testimony","media"], t:"The Disclosure Project", p:"National Press Club, Washington, D.C.",
  s:`Physician Steven Greer put about twenty retired military, FAA and intelligence witnesses in front of the press. They described radar cases, nuclear base incidents and recovered craft, and said they would testify under oath. It set the model for every later whistleblower event.`,
  c:`The accounts were unsworn and uneven in quality, and Congress did not act. Greer's later paid contact expeditions damaged his standing with many researchers.`,
  w:"Disclosure Project", v:"Disclosure Project 2001 National Press Club full" },
{ y:2002.2, d:"2001 to 2002", e:"e", k:"clm", g:["gov","media"], t:"Gary McKinnon looks inside", p:"London, England",
  s:`A Scottish systems administrator broke into 97 US military and NASA computers hunting for hidden UFO files. He says he saw a spreadsheet headed "Non-Terrestrial Officers", ship-to-ship transfer logs for vessels that do not exist, and a NASA image of a cigar-shaped craft.`,
  c:`He saved nothing. The US spent a decade trying to extradite him for the damage, and Britain blocked it in 2012 on health grounds.`,
  w:"Gary McKinnon", v:"Gary McKinnon hack NASA non-terrestrial officers" },
{ y:2004.87, d:"14 November 2004", e:"e", k:"rec", g:["sighting","gov","navy"], t:"The Nimitz Tic Tac", p:"Pacific Ocean, off San Diego and Baja",
  s:`The cruiser USS Princeton had tracked objects dropping from 80,000 feet to the sea surface for days. Cmdr. David Fravor and Lt. Cmdr. Alex Dietrich were sent to look. Over a patch of churning water they saw a smooth white oblong about 40 feet long with no wings or exhaust. It mirrored Fravor's descent, then shot out of sight and reappeared on radar 60 miles away at their rendezvous point. A later flight recorded the FLIR1 video.`,
  c:`The video alone shows a distant blob that a jet could explain. The case rests on four aviators and the radar operators, since the ship's radar data has never been released.`,
  w:"USS Nimitz UFO incident", v:"David Fravor Nimitz Tic Tac interview FLIR1" },
{ y:2006.85, d:"7 November 2006", e:"e", k:"wit", g:["sighting"], t:"A disc over gate C17", p:"O'Hare International Airport, Chicago",
  s:`About a dozen United Airlines ramp workers, pilots and managers watched a dark grey disc hover below the overcast above a gate for several minutes, then shoot straight up and leave a clean round hole in the cloud. The story came out when the Chicago Tribune obtained a recording of a supervisor calling the tower.`,
  c:`The FAA called it a weather phenomenon and did not investigate. Nothing appeared on radar and nobody took a usable photo.`,
  w:"2006 O'Hare International Airport UFO sighting", v:"2006 O'Hare airport UFO" },
{ y:2008, d:"2007 to 2012", e:"e", k:"rec", g:["gov"], t:"AAWSAP and AATIP, the secret program", p:"Defense Intelligence Agency",
  s:`At the urging of Senate leader Harry Reid, Congress quietly set aside 22 million dollars. The contract went to Robert Bigelow's company, which studied military encounters, the Skinwalker Ranch in Utah, and commissioned 38 technical papers on subjects such as warp drives and metamaterials. Program manager James Lacatski later wrote that the US holds a craft of unknown origin.`,
  c:`The Pentagon says the program's formal subject was future aerospace threats and that it ended in 2012. AARO reported in 2024 that it produced no evidence of non-human technology.`,
  w:"Advanced Aerospace Threat Identification Program", v:"AAWSAP AATIP Skinwalkers at the Pentagon Lacatski" },
{ y:2009, d:"2006 to 2013", e:"e", k:"rec", g:["gov"], t:"Britain opens its files", p:"London, England",
  s:`The Ministry of Defence released its secret Project Condign study, which accepted that unexplained aerial phenomena exist and suggested rare atmospheric plasmas. It then closed its UFO desk in 2009 and transferred about 60,000 pages of sighting files to the National Archives.`,
  c:`Officials said that in over fifty years no report had shown a threat to the UK, and that the desk served no defence purpose.`,
  w:"Project Condign", v:"UK Ministry of Defence UFO files released",
  l:[["UK National Archives: UFO files","https://www.nationalarchives.gov.uk/ufos/"]] },
{ y:2013.31, d:"25 April 2013", e:"e", k:"rec", g:["sighting","gov"], t:"The Aguadilla object", p:"Rafael Hernández Airport, Puerto Rico",
  s:`A US Customs and Border Protection aircraft filmed a small warm object on its thermal camera for about three minutes. It crosses the airport at night without lights, appears to enter the ocean and come out again without slowing, and then seems to split in two.`,
  c:`AARO told the Senate in 2024 that it judged the plunge an imaging effect and the object likely a pair of drifting lanterns or balloons. An independent scientific group that studied the video disagrees.`,
  w:"Aguadilla UFO 2013 Puerto Rico thermal video", v:"Aguadilla Puerto Rico 2013 UAP thermal video" },
{ y:2015.05, d:"2014 to 2015", e:"e", k:"rec", g:["sighting","gov","navy"], t:"Gimbal, GoFast and the daily visitors", p:"Atlantic coast, Virginia to Florida",
  s:`After a radar upgrade, F/A-18 squadrons from the USS Theodore Roosevelt began detecting objects in their training ranges almost every day. Lt. Ryan Graves says they stayed aloft for hours at speeds from zero to supersonic, and that one pilot nearly hit a dark cube inside a clear sphere. Crews recorded the Gimbal and GoFast videos in January 2015.`,
  c:`AARO assessed GoFast as an object at about 13,000 feet moving at wind speed, with parallax creating the impression of speed. Analyst Mick West attributes the Gimbal rotation to the camera mount.`,
  w:"Pentagon UFO videos", v:"Ryan Graves Gimbal GoFast Roosevelt UAP" },

/* ───────────── F · The disclosure era ───────────── */
{ y:2017.96, d:"16 December 2017", e:"f", k:"rec", g:["media","gov"], t:"The New York Times breaks the story", p:"New York",
  s:`Leslie Kean, Ralph Blumenthal and Helene Cooper revealed the Pentagon's secret UFO program on the front page, with two Navy videos and on-record interviews with its former head Luis Elizondo and Senator Harry Reid. Former defence official Christopher Mellon had helped get the videos out. Serious coverage of the subject starts here.`,
  c:`The Pentagon has disputed Elizondo's exact role. The story's line about recovered alloys stored in modified buildings has never been substantiated.`,
  w:"Pentagon UFO videos", v:"2017 New York Times Pentagon UFO program Elizondo",
  l:[["The original New York Times story","https://www.nytimes.com/2017/12/16/us/politics/pentagon-program-ufo-harvard-reid.html"]] },
{ y:2019.6, d:"April to September 2019", e:"f", k:"rec", g:["gov","navy","sighting"], t:"The Navy says the videos are real", p:"Washington and the California coast",
  s:`The Navy wrote new rules so pilots could report unknown objects without stigma, and a spokesman confirmed that the three leaked videos show unidentified aerial phenomena. That July, warships off southern California logged swarms of unknown objects over several nights. One clip shows a sphere dropping into the sea.`,
  c:`Ship logs point to drones for much of the July activity. A widely shared clip of green pyramids is an out-of-focus camera aperture effect, as the Pentagon later said.`,
  w:"USS Omaha UFO 2019 Navy warships drone swarm", v:"USS Omaha 2019 UAP sphere splash video" },
{ y:2020.32, d:"27 April 2020", e:"f", k:"rec", g:["gov"], t:"The Pentagon releases the videos itself", p:"The Pentagon",
  s:`The Department of Defense officially published FLIR1, Gimbal and GoFast and said the objects in them remain unidentified. In August it created the Unidentified Aerial Phenomena Task Force under Navy intelligence.`,
  c:`The statement stressed that releasing the footage revealed no sensitive capability. It made no claim about what the objects were.`,
  w:"Unidentified Aerial Phenomena Task Force", v:"Pentagon officially releases three UFO videos 2020",
  l:[["Department of Defense statement","https://www.defense.gov/News/Releases/Release/Article/2165713/statement-by-the-department-of-defense-on-the-release-of-historical-navy-videos/"]] },
{ y:2021.48, d:"25 June 2021", e:"f", k:"rec", g:["gov"], t:"The intelligence community's first assessment", p:"Office of the Director of National Intelligence",
  s:`A nine-page public report covered 144 military reports from 2004 to 2021. It could explain one, a deflating balloon. Eighty involved more than one sensor, eleven were near misses with aircraft, and eighteen described unusual movement such as holding still in wind or sudden acceleration with no visible propulsion.`,
  c:`The report blamed poor data for most of the gap and listed clutter, natural phenomena, US or foreign programs and "other" as the possible bins.`,
  w:"UFO Report (U.S. Intelligence)", v:"ODNI preliminary assessment UAP June 2021",
  l:[["Read the report (PDF)","https://www.dni.gov/files/ODNI/documents/assessments/Prelimary-Assessment-UAP-20210625.pdf"]] },
{ y:2022.38, d:"17 May 2022", e:"f", k:"rec", g:["gov","testimony"], t:"The first open hearing in over 50 years", p:"House Intelligence subcommittee",
  s:`Two senior defence officials testified in public, showed new footage and said the task force's database had grown to about 400 reports. In July, Congress and the Pentagon created the All-domain Anomaly Resolution Office, AARO, with authority across air, sea and space.`,
  c:`Officials said they had seen nothing that pointed beyond Earth, and one clip shown to the committee was explained on the spot as a camera effect.`,
  w:"All-domain Anomaly Resolution Office", v:"May 2022 House Intelligence UAP hearing Bray Moultrie",
  l:[["AARO","https://www.aaro.mil/"]] },
{ y:2023.11, d:"4 to 12 February 2023", e:"f", k:"rec", g:["gov","sighting"], t:"Four shootdowns in eight days", p:"South Carolina, Alaska, Yukon, Lake Huron",
  s:`After a US fighter destroyed a Chinese surveillance balloon, NORAD widened its radar filters and jets shot down three more small objects, described as cylindrical and octagonal. A missile fired at the last one missed. Little or no debris from the three was recovered or shown.`,
  c:`President Biden said they were most likely private or research balloons. A hobby club reported one of its balloons missing along the Yukon track.`,
  w:"2023 high-altitude object events", v:"February 2023 objects shot down Alaska Yukon Lake Huron" },
{ y:2023.43, d:"5 June 2023", e:"f", k:"clm", g:["testimony","retrieval","media"], t:"David Grusch goes public", p:"The Debrief and NewsNation",
  s:`A decorated Air Force intelligence officer who had served on the UAP Task Force said the US has run a decades-long program to recover and reverse engineer craft of non-human origin, hidden from Congress. He had filed a whistleblower complaint, and the intelligence community's inspector general judged it credible and urgent.`,
  c:`Grusch says he was told this by people in the program and has not seen craft himself. The inspector general's finding concerned his reprisal complaint. It was not a ruling on whether the craft exist.`,
  w:"David Grusch UFO whistleblower claims", v:"David Grusch NewsNation Ross Coulthart interview",
  l:[["The Debrief's original report","https://thedebrief.org/intelligence-officials-say-u-s-has-retrieved-non-human-craft/"]] },
{ y:2023.57, d:"26 July 2023", e:"f", k:"rec", g:["testimony","gov","navy"], t:"Under oath: Grusch, Fravor and Graves", p:"House Oversight subcommittee",
  s:`Fravor described the Tic Tac as far beyond any technology he knew. Graves said military and airline crews see such objects routinely and under-report them. Grusch testified that the US holds crashed craft and that "non-human biologics" were recovered with some of them, and offered names and locations in a closed session.`,
  c:`Grusch's knowledge is second-hand, and the Pentagon denied his claims the same day. Members were refused a secure room to hear the details.`,
  w:"United States House Oversight Subcommittee hearing on UAP July 2023", v:"July 26 2023 UAP hearing full Grusch Fravor Graves",
  l:[["Hearing page and video","https://oversight.house.gov/hearing/unidentified-anomalous-phenomena-implications-on-national-security-public-safety-and-government-transparency/"]] },
{ y:2023.7, d:"12 to 14 September 2023", e:"f", k:"rec", g:["gov","media"], t:"NASA reports, and Mexico is shown mummies", p:"Washington and Mexico City",
  s:`NASA's independent study team found no evidence that UAP are extraterrestrial, said the data is too poor to rule anything in or out, and appointed a director of UAP research. Two days earlier, journalist Jaime Maussan had shown Mexico's Congress two small three-fingered bodies he said were a thousand years old and not human.`,
  c:`Peruvian forensic scientists who examined similar figures found dolls built from human and animal bones with modern glue. Researchers regard the Maussan bodies as a looting and fraud story.`,
  w:"NASA UAP independent study team", v:"NASA UAP report September 2023 press conference",
  l:[["NASA's UAP study","https://science.nasa.gov/uap/"]] },
{ y:2023.95, d:"July to December 2023", e:"f", k:"rec", g:["gov","law"], t:"The UAP Disclosure Act is written, then gutted", p:"US Senate",
  s:`Majority Leader Chuck Schumer and Republican Mike Rounds proposed a review board modelled on the JFK records law. Their text defined "non-human intelligence" and gave the government eminent domain over any recovered craft or biological evidence held by contractors. The Senate passed it.`,
  c:`House negotiators removed the review board and the seizure power. What survived was a records collection at the National Archives. Sponsors blamed committee chairs with large defence contractors in their districts.`,
  w:"National Defense Authorization Act for Fiscal Year 2024 UAP Disclosure Act", v:"Schumer Rounds UAP Disclosure Act explained",
  l:[["National Archives UAP records collection","https://www.archives.gov/research/topics/uaps"]] },
{ y:2024.02, d:"9 January 2024", e:"f", k:"wit", g:["sighting","media"], t:"The jellyfish", p:"Joint base, Iraq, filmed 2018",
  s:`Filmmaker Jeremy Corbell released military thermal footage of an irregular object with dangling appendages drifting over a base. He says it was invisible to night vision, went into a lake and later left at speed. Personnel on the base have described it since.`,
  c:`Analysts see a cluster of party balloons carried on the wind at a steady speed and height. The part of the story where it enters water and accelerates is not in the released clip.`,
  w:"Jellyfish UFO video Iraq 2018 Corbell", v:"jellyfish UAP Iraq 2018 thermal video Corbell" },
{ y:2024.19, d:"8 March 2024", e:"f", k:"rec", g:["gov"], t:"AARO's history report says there is nothing", p:"The Pentagon",
  s:`After interviewing about 30 people and reviewing records back to 1945, AARO reported no evidence that any US program has held or reverse engineered non-human technology. It said the retrieval story spreads within a small circle repeating each other's claims, and disclosed a proposed program called Kona Blue that was never approved because it had nothing to study.`,
  c:`Whistleblowers and several lawmakers call the report a whitewash, say key witnesses refused to speak to AARO, and list factual errors. Its author, Sean Kirkpatrick, had already left.`,
  w:"All-domain Anomaly Resolution Office historical record report", v:"AARO historical record report volume 1 March 2024",
  l:[["AARO reports","https://www.aaro.mil/"]] },
{ y:2024.39, d:"21 May 2024", e:"f", k:"clm", g:["testimony"], t:"A colonel says there is zero doubt", p:"SALT conference, New York",
  s:`Retired Army colonel Karl Nell, who had worked with the UAP Task Force and with Grusch, told an audience of investors that non-human intelligence exists and has long interacted with humanity. Asked how sure he was, he said there was "zero doubt". He gave six reasons for secrecy, among them national security and fear of social disruption.`,
  c:`Nell offered no evidence, only the list of officials who have said similar things. He holds that the proof exists and is classified.`,
  w:"Karl Nell", v:"Karl Nell zero doubt SALT 2024" },
{ y:2024.87, d:"13 November 2024", e:"f", k:"rec", g:["testimony","gov"], t:"Exposing the Truth", p:"House Oversight subcommittees",
  s:`Luis Elizondo testified that the US and adversaries hold non-human technology. Retired Rear Admiral Tim Gallaudet described a Navy email about a near miss that was deleted from his inbox. Journalist Michael Shellenberger submitted a report on an alleged Pentagon program, Immaculate Constellation, said to collect the best UAP imagery. Former Pentagon adviser Matthew Brown later identified himself as its author.`,
  c:`The Pentagon said it has no record of any program by that name. No witness brought documents or imagery that the public could check.`,
  w:"Immaculate Constellation", v:"November 13 2024 UAP hearing Elizondo Gallaudet Shellenberger",
  l:[["Hearing page and video","https://oversight.house.gov/hearing/unidentified-anomalous-phenomena-exposing-the-truth/"]] },
{ y:2024.88, d:"14 to 19 November 2024", e:"f", k:"rec", g:["gov"], t:"1,652 reports, 21 with no answer", p:"AARO annual report and Senate hearing",
  s:`AARO reported 757 new cases, bringing its total to 1,652. Of the cases it closed that year, about 70 percent were balloons and 16 percent drones. New director Jon Kosloski told senators that 21 cases had him and his colleagues stumped, and described a small share with characteristics the office cannot account for.`,
  c:`Kosloski repeated that the office has found no verifiable evidence of extraterrestrial beings, activity or technology.`,
  w:"All-domain Anomaly Resolution Office", v:"Kosloski AARO Senate hearing November 2024",
  l:[["AARO","https://www.aaro.mil/"]] },
{ y:2024.92, d:"November to December 2024", e:"f", k:"rec", g:["sighting","gov"], t:"The New Jersey drones", p:"New Jersey and the Northeast",
  s:`Residents, police and a military arsenal reported large drones flying nightly. Airspace was closed over several sites, thousands of tips reached the FBI, and members of Congress demanded answers. It showed how fast an unexplained sky can become a national event.`,
  c:`Federal agencies found mostly crewed aircraft, hobby drones and stars. In January 2025 the White House said many flights were authorised research.`,
  w:"2024 United States drone sightings", v:"New Jersey drones December 2024 explained" },
{ y:2025.05, d:"18 January 2025", e:"f", k:"clm", g:["testimony","retrieval","specops"], t:"Jake Barber and the egg", p:"NewsNation",
  s:`A former Air Force combat controller turned contract helicopter pilot said he lifted a white, seamless, egg-shaped craft on a long line during a retrieval mission, and that it was not human-made. NewsNation aired a short clip of a pale object slung under a helicopter. Barber also said trained "psionic" operators can call craft in, and founded a group, Skywatcher, to show it.`,
  c:`Three former special operators vouched for his background, but nobody has verified the clip's date, place or contents. The psychic element lost him part of the audience he had gained.`,
  w:"Jake Barber UFO whistleblower egg", v:"Jake Barber NewsNation egg UAP retrieval",
  l:[["NewsNation's report","https://www.newsnationnow.com/space/ufo/hfr-uap-recovery-video-egg-shaped-object-exclusive/"]] },
{ y:2025.5, d:"1 July 2025", e:"f", k:"rec", g:["science"], t:"An interstellar visitor: 3I/ATLAS", p:"Río Hurtado, Chile",
  s:`A survey telescope found the third known object from outside the solar system, moving faster than the first two. Harvard astronomer Avi Loeb, who had argued in 2018 that the first, 'Oumuamua, might be an artificial light sail, urged that this one be checked for signs of technology as it passed the Sun in late October.`,
  c:`Observatories and NASA describe an active comet with a coma and tail. Loeb himself rated a natural origin as most likely.`,
  w:"3I/ATLAS", v:"3I/ATLAS interstellar object Avi Loeb" },
{ y:2025.69, d:"9 September 2025", e:"f", k:"rec", g:["testimony","gov","navy"], t:"Whistleblowers and a missile that bounced", p:"House Task Force on Declassification",
  s:`Air Force veteran Dylan Borland described a 100-foot triangle lifting off near Langley in 2012, and years of career reprisal. Jeffrey Nuccetelli recounted five incursions at Vandenberg from 2003 to 2005. Serving Navy senior chief Alexandro Wiggins said a glowing Tic Tac rose from the sea beside USS Jackson in 2023. Rep. Eric Burlison showed drone footage from off Yemen in which a Hellfire missile strikes an orb that flies on.`,
  c:`Skeptical analysts argue the Yemen video shows a missile passing through or glancing off a balloon or drone, with debris visible afterwards. The Pentagon has not confirmed what it shows.`,
  w:"Restoring Public Trust Through UAP Transparency and Whistleblower Protection hearing 2025", v:"September 9 2025 UAP hearing Borland Nuccetelli Wiggins Yemen Hellfire",
  l:[["Hearing page and video","https://oversight.house.gov/hearing/restoring-public-trust-through-uap-transparency-and-whistleblower-protection/"]] },
{ y:2025.8, d:"October 2025", e:"f", k:"rec", g:["science","nuclear"], t:"Lights in the sky before Sputnik", p:"Palomar Observatory plates, 1949 to 1957",
  s:`A team led by astronomer Beatriz Villarroel published peer-reviewed studies of star-like flashes on photographic plates taken before any satellite existed. They report that the flashes thin out in Earth's shadow, as sunlit reflective objects in orbit would, and that they cluster on days around nuclear weapons tests and UAP reports.`,
  c:`Other astronomers think most of the flashes are defects in the photographic emulsion or copying process. The claim needs original plates and independent teams.`,
  w:"Beatriz Villarroel", v:"Beatriz Villarroel transients Palomar plates nuclear tests" },
{ y:2025.89, d:"21 November 2025", e:"f", k:"clm", g:["media","testimony","retrieval"], t:"The Age of Disclosure", p:"Cinemas and streaming",
  s:`Dan Farah's documentary put 34 current and former officials on the record, among them Secretary of State Marco Rubio, senators from both parties and a former Director of National Intelligence. Former UAP Task Force director Jay Stratton says on camera: "I have seen with my own eyes nonhuman craft and nonhuman beings." The film describes an 80-year cover-up and a secret race among nations to reverse engineer what they hold.`,
  c:`The film presents testimony and no physical evidence. Rubio describes what he has been told and stops short of endorsing it. Critics' reviews were poor and audience scores high.`,
  w:"The Age of Disclosure", v:"The Age of Disclosure official trailer" },
{ y:2026.14, d:"19 February 2026", e:"f", k:"rec", g:["gov"], t:"A president orders the files opened", p:"Washington, D.C.",
  s:`Days after former president Barack Obama said on a podcast that aliens were real, then clarified he had seen no evidence of contact, President Donald Trump announced that he was directing the Secretary of War and other agencies to identify and release government files on alien life, UAP and UFOs. He told reporters he did not know whether they were real.`,
  c:`It was a public directive, and its legal form was not specified. A House deadline for the Pentagon to hand over specific videos passed in April with nothing delivered.`,
  w:"United States UFO files", v:"Trump orders release UFO files February 2026" },
{ y:2026.35, d:"8 May 2026 onward", e:"f", k:"rec", g:["gov"], t:"PURSUE: the government publishes its own UFO files", p:"war.gov/ufo",
  s:`The Pentagon launched a public archive and has posted seven tranches so far, 478 files by the seventh on 23 October 2026, from more than 160 files and 20 videos in the first to batches drawn from the CIA, FBI, NASA and the Department of Energy. One AARO memo dated June 2026 covers six federal agents who watched an orange orb release smaller red ones over two evenings in 2023 near a sensitive site. The case is still open.`,
  c:`Officials say nothing in the files confirms extraterrestrial life. Skeptics found smears, balloons and material public for decades. Advocates note there is nothing on crash retrievals and say that proves the real files sit elsewhere.`,
  w:"United States UFO files", v:"PURSUE UFO files release war.gov orbs launching orbs",
  l:[["The PURSUE archive","https://www.war.gov/ufo/"]] },
{ y:2026.45, d:"9 and 25 June 2026", e:"f", k:"rec", g:["testimony","gov"], t:"Disclosure goes institutional", p:"Capitol steps and the Russell Senate Office Building",
  s:`Grusch returned to the Capitol with Representatives Luna, Burchett, Burlison and Moskowitz to demand immunity for insiders and an audit of hidden spending. Two weeks later the Disclosure Foundation, chaired by Christopher Mellon, filled the Kennedy Caucus Room for a day-long forum with Senators Rounds and Gillibrand, scientists and former officials.`,
  c:`Both events asked for evidence to be released. Neither produced any. Avi Loeb, who attended, wrote that nothing public so far clearly exceeds human technology.`,
  w:"Disclosure Foundation Disclosure Forum 2026", v:"June 9 2026 Grusch Capitol press conference" },
{ y:2026.56, d:"21 to 22 July 2026", e:"f", k:"rec", g:["gov","law"], t:"NDAs waived, and the House passes a review board", p:"White House and House floor",
  s:`The administration directed agencies to waive nondisclosure agreements for current and former staff and contractors who bring UAP information to AARO or the PURSUE team. The next day the House adopted Burlison's UAP Disclosure Act as an amendment to the defence bill. It would create an independent, Senate-confirmed review board with subpoena power and reach into contractors.`,
  c:`An official stressed that the waiver is not a declassification order and applies only inside government channels. The amendment still has to survive the Senate and the final negotiation that killed it in 2023.`,
  w:"UAP Disclosure Act", v:"Burlison UAP Disclosure Act amendment July 2026 NDA waiver",
  l:[["Burlison's statement on the amendment","https://burlison.house.gov/media/press-releases/house-adopts-burlison-amendment-establishing-uap-disclosure-framework"]] },
{ y:2026.85, d:"November 2026", e:"f", k:"rec", g:["gov"], t:"Where it stands", p:"As of this page's last update",
  s:`The members of the House UAP Caucus who were on the ballot kept their seats in the midterms. PURSUE releases continue. The review board is unsettled. Dozens of officials have now said on the record that a hidden program exists, and the offices charged with finding it say they have looked and found nothing.`,
  c:`No craft, material or body has been shown to the public or to independent scientists. That one fact is what separates the documented story from the claimed one, and any real disclosure would have to close it.`,
  w:"United States UFO files", v:"UAP disclosure news" }
];
